     1	// Totals for an invoice. Prices are in cents.
     2	export function subtotal(lines) {
     3	  return lines.reduce((sum, line) => sum + line.price * line.qty, 0);
     4	}
     5	
     6	export function applyDiscount(amount, percent) {
     7	  // BUG: percent is treated as a fraction already
     8	  return Math.round(amount - amount * percent);
     9	}
    10	
    11	export function total(lines, discountPercent = 0, taxRate = 0.1) {
    12	  const discounted = applyDiscount(subtotal(lines), discountPercent);
    13	  return Math.round(discounted * (1 + taxRate));
    14	}
